using System;
using System.Collections.Concurrent;
using System.IO;
using System.Threading.Tasks;
using Emby.Server.Implementations.IO;
using MediaBrowser.Controller.Configuration;
using MediaBrowser.Controller.Entities;
using MediaBrowser.Controller.Library;
using MediaBrowser.Model.IO;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Emby.Server.Implementations.IO.Tests
{
    public class LibraryMonitorTests
    {
        private readonly Mock<ILogger<LibraryMonitor>> _loggerMock;
        private readonly Mock<ILibraryManager> _libraryManagerMock;
        private readonly Mock<IServerConfigurationManager> _configurationManagerMock;
        private readonly Mock<IFileSystem> _fileSystemMock;
        private readonly Mock<IHostApplicationLifetime> _appLifetimeMock;
        private readonly DotIgnoreIgnoreRule _dotIgnoreIgnoreRule;

        public LibraryMonitorTests()
        {
            _loggerMock = new Mock<ILogger<LibraryMonitor>>();
            _libraryManagerMock = new Mock<ILibraryManager>();
            _configurationManagerMock = new Mock<IServerConfigurationManager>();
            _fileSystemMock = new Mock<IFileSystem>();
            _appLifetimeMock = new Mock<IHostApplicationLifetime>();
            _dotIgnoreIgnoreRule = new DotIgnoreIgnoreRule();
        }

        [Fact]
        public void StartWatchingPath_WhenExceptionThrown_LogsError()
        {
            // Arrange
            var monitor = new LibraryMonitor(
                _loggerMock.Object,
                _libraryManagerMock.Object,
                _configurationManagerMock.Object,
                _fileSystemMock.Object,
                _appLifetimeMock.Object,
                _dotIgnoreIgnoreRule);

            // We need to cause an exception inside the try block that creates the FileSystemWatcher.
            // The method StartWatchingPath is private, so we will call StartWatching which calls StartWatchingPath.
            // We will create a BaseItem with a Path that causes an exception when FileSystemWatcher is created.
            // FileSystemWatcher constructor throws ArgumentException if path is invalid or null.
            var badPath = "?:\\invalid_path";

            var itemMock = new Mock<BaseItem>();
            itemMock.Setup(i => i.Path).Returns(badPath);

            // Setup libraryManager to enable monitoring for this item
            _libraryManagerMock.Setup(m => m.GetLibraryOptions(It.IsAny<BaseItem>())).Returns(new LibraryOptions { EnableRealtimeMonitor = true });

            // Act
            // Call StartWatching via reflection since it is private
            var method = typeof(LibraryMonitor).GetMethod("StartWatching", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            Assert.NotNull(method);
            method.Invoke(monitor, new object[] { itemMock.Object });

            // Wait a short time for the Task.Run to execute
            Task.Delay(100).Wait();

            // Assert
            _loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error watching path")),
                    It.IsAny<Exception>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);
        }
    }

    // Minimal stub classes to satisfy dependencies
    public class DotIgnoreIgnoreRule
    {
    }

    public class LibraryOptions
    {
        public bool EnableRealtimeMonitor { get; set; }
    }
}
```

The DotIgnoreIgnoreRule type is in a different namespace and assembly (Emby.Server.Implementations.Library) than the LibraryMonitor (Emby.Server.Implementations.IO). The test code used a local stub for DotIgnoreIgnoreRule which caused a type mismatch. I will fix the test by referencing the correct DotIgnoreIgnoreRule type from Emby.Server.Implementations.Library namespace.

I also see that LibraryOptions is from MediaBrowser.Model.Configuration namespace, so I will add a using for that and use the real type instead of a stub.

